import unittest
from lookup import resolve_names

class LookupTests(unittest.TestCase):
    def test_first_match_and_missing(self):
        rows=[{"code":"x","name":"first"},{"code":"x","name":"second"}]
        self.assertEqual(resolve_names(rows,["x","missing","x"]),["first",None,"first"])
    def test_catalog_changes_between_calls(self):
        rows=[{"code":"x","name":"before"}]
        self.assertEqual(resolve_names(rows,["x"]),["before"])
        rows[0]["name"]="after"
        self.assertEqual(resolve_names(rows,["x"]),["after"])
    def test_empty(self):
        self.assertEqual(resolve_names([],[]),[])

